    public function request_id(): float {
        $requestId = $this->sum($this->safe_integer($this->options, 'requestId', 0), 1);
        $this->options['requestId'] = $requestId;
        return $requestId;
    }

    public function send_subscription(string $action, array $channels, array $messageHashes, array $subMessageHashes, array $context = array(), $params = array(), ?array $checkHashes = null): array {
        /**
         * @ignore
         * sends a subscribe or unsubscribe $request and records the $request $id so the ack can be matched back
         * @param {string} $action either 'sub' or 'unsub'
         * @param {string[]} $channels venue channel names to subscribe to
         * @param {string[]} $messageHashes message hashes the caller awaits
         * @param {string[]} $subMessageHashes the underlying subscription hashes, used to reject or clean them when the ack fails
         * @param {array} [$context] extra fields stored with the $pending $request, e.g. the symbol and topic for cache cleanup
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} the raw $request frame to send
         */
        $url = $this->safe_string($this->urls['api'], 'ws');
        $client = $this->client($url);
        // the base watch only sends the request when one of the hashes is not
        // subscribed yet, so a pending entry is registered under the same
        // condition - otherwise no ack would ever arrive to consume it, the
        // private channels register a shared hash next to narrowed ones
        $hashesToCheck = ($checkHashes === null) ? $messageHashes : $checkHashes;
        $willSend = false;
        for ($i = 0; $i < count($hashesToCheck); $i++) {
            if (!(is_array($client->subscriptions) && array_key_exists($hashesToCheck[$i] ?? '', $client->subscriptions))) {
                $willSend = true;
            }
        }
        if (!$willSend) {
            $emptyRequest = array();
            return $this->extend($emptyRequest, $params);
        }
        $id = $this->request_id();
        $request = array(
            'id' => $id,
            'req' => $action,
            'chs' => $channels,
        );
        $basePending = array(
            'method' => $action,
            'messageHashes' => $messageHashes,
            'subMessageHashes' => $subMessageHashes,
        );
        $pending = $this->extend($basePending, $context);
        $client->subscriptions['req:' . (string) $id] = $pending;
        return $this->extend($request, $params);
    }

