    public function handle_order_book(Client $client, array $message) {
        //
        //     {
        //         "ch": "book::1",
        //         "ts": 1788546815589,
        //         "ets": 1788546815543,
        //         "sq": 35879871598,
        //         "data": {
        //             "a": [ [ "7715.7", "0.31631" ] ],
        //             "b": [ [ "7715.6", "7.43477" ] ]
        //         }
        //     }
        //
        // every frame is a full snapshot of the top twenty levels, deltas are never sent
        //
        $ch = $this->safe_string($message, 'ch', '');
        $parts = explode('::', $ch);
        $marketId = $this->safe_string($parts, 1);
        $market = $this->safe_market($marketId);
        $symbol = $this->safe_string($market, 'symbol', '');
        $data = $this->safe_dict($message, 'data', array());
        $timestamp = $this->safe_integer($message, 'ts');
        $snapshot = $this->parse_order_book($data, $symbol, $timestamp, 'b', 'a');
        $snapshot['nonce'] = $this->safe_integer($message, 'sq');
        if (!(is_array($this->orderbooks) && array_key_exists($symbol ?? '', $this->orderbooks))) {
            $ob = $this->order_book($snapshot);
            $this->orderbooks[$symbol] = $ob;
        }
        $orderbook = $this->orderbooks[$symbol];
        $orderbook->reset($snapshot);
        $messageHash = 'orderbook:' . $symbol;
        $client->resolve($orderbook, $messageHash);
    }

