    private function do_watch_tickers(?array $symbols = null, $params = array()) {
        /**
         * watches price tickers for multiple markets, the venue fans the all-instruments channel out into one frame per instrument
         *
         * @see https://docs.polymarket.com/perps/realtime-updates
         *
         * @param {string[]} [$symbols] unified $symbols of the markets to fetch the ticker for, all $market tickers are streamed if not assigned
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/#/?id=ticker-structure ticker structures~
         */
        Async\await($this->load_markets());
        $symbolsNormalized = $this->market_symbols($symbols);
        $url = $this->safe_string($this->urls['api'], 'ws');
        $messageHashes = array();
        $channels = array();
        if ($symbolsNormalized === null) {
            $messageHashes[] = 'tickers';
            $channels[] = 'tickers::all';
        } else {
            for ($i = 0; $i < count($symbolsNormalized); $i++) {
                $market = $this->market($symbolsNormalized[$i]);
                $messageHashes[] = 'ticker:' . $this->safe_string($market, 'symbol', '');
                $channels[] = 'tickers::' . $this->safe_string($market, 'id', '');
            }
        }
        $request = $this->send_subscription('sub', $channels, $messageHashes, $messageHashes, array(), $params);
        $newTicker = Async\await($this->watch_multiple($url, $messageHashes, $request, $messageHashes));
        if ($this->newUpdates) {
            $result = array();
            $result[$newTicker['symbol']] = $newTicker;
            return $result;
        }
        return $this->filter_by_array($this->tickers, 'symbol', $symbolsNormalized);
    }

    public function handle_ticker(Client $client, array $message) {
        //
