    public function handle_trades(Client $client, array $message) {
        //
        //     {
        //         "ch": "trades::1",
        //         "ts": 1788546815589,
        //         "ets": 1788546815543,
        //         "sq": 35879871600,
        //         "data": {
        //             "tid": 3738280849593744,
        //             "iid": 1,
        //             "side": "long",
        //             "p": "7714",
        //             "qty": "0.00136",
        //             "ts": 1788546565789,
        //             "hash": "0x"
        //         }
        //     }
        //
        // the asyncapi spec describes the data field as an array of trade objects while typing it
        // as a single object, so both shapes are handled here
        //
        $data = $this->safe_value($message, 'data');
        $rows = array();
        if ((gettype($data) === 'array' && array_keys($data) === array_keys(array_keys($data)))) {
            $rows = $data;
        } else {
            $rows[] = $data;
        }
        $rowsLength = count($rows);
        if ($rowsLength === 0) {
            return;
        }
        $first = $this->safe_dict($rows, 0, array());
        $marketId = $this->safe_string($first, 'iid');
        $market = $this->safe_market($marketId);
        $symbol = $this->safe_string($market, 'symbol', '');
        if (!(is_array($this->trades) && array_key_exists($symbol ?? '', $this->trades))) {
            $limit = $this->safe_integer($this->options, 'tradesLimit', 1000);
            $stored = new ArrayCache($limit);
            $this->trades[$symbol] = $stored;
        }
        $trades = $this->trades[$symbol];
        for ($i = 0; $i < $rowsLength; $i++) {
            $row = $this->safe_dict($rows, $i, array());
            $trade = $this->parse_ws_trade($row, $market);
            $trades->append($trade);
        }
        $messageHash = 'trade:' . $symbol;
        $client->resolve($trades, $messageHash);
    }

    public function parse_ws_trade(array $trade, ?array $market = null): array {
        //
        //     {
        //         "tid": 3738280849593744,
        //         "iid": 1,
        //         "side": "long",
        //         "p": "7714",
        //         "qty": "0.00136",
        //         "ts": 1788546565789,
        //         "hash": "0x"
        //     }
        //
        $marketId = $this->safe_string($trade, 'iid');
        $marketResolved = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer($trade, 'ts');
        $side = $this->safe_string_lower($trade, 'side');
        if ($side === 'long') {
            $side = 'buy';
        } elseif ($side === 'short') {
            $side = 'sell';
        }
        return $this->safe_trade(array(
            'id' => $this->safe_string($trade, 'tid'),
            'info' => $trade,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'symbol' => $marketResolved['symbol'],
            'order' => null,
            'type' => null,
            'side' => $side,
            'takerOrMaker' => null,
            'price' => $this->safe_string($trade, 'p'),
            'amount' => $this->safe_string($trade, 'qty'),
            'cost' => null,
            'fee' => null,
        ), $marketResolved);
    }

