    private function do_watch_ohlcv(string $symbol, string $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * watches historical candlestick data containing the open, high, low, close price, and the volume of a $market
         *
         * @see https://docs.polymarket.com/perps/realtime-updates
         *
         * @param {string} $symbol unified $symbol of the $market to fetch OHLCV data for
         * @param {string} $timeframe the length of time each candle represents, the 1s $timeframe is not available over the websocket
         * @param {int} [$since] timestamp in ms of the earliest candle to fetch
         * @param {int} [$limit] the maximum amount of candles to fetch
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $symbolResolved = $this->safe_string($market, 'symbol', '');
        $wsTimeframes = $this->safe_dict($this->options, 'wsTimeframes', array());
        $interval = $this->safe_string($wsTimeframes, $timeframe);
        if ($interval === null) {
            throw new NotSupported($this->id . ' watchOHLCV() does not support the ' . $timeframe . ' timeframe over the websocket');
        }
        $messageHash = 'candles:' . $timeframe . ':' . $symbolResolved;
        $channel = 'klines::' . $this->safe_string($market, 'id', '') . '::' . $interval;
        $request = $this->send_subscription('sub', array( $channel ), array( $messageHash ), array( $messageHash ), array(), $params);
        $url = $this->safe_string($this->urls['api'], 'ws');
        $ohlcv = Async\await($this->watch($url, $messageHash, $request, $messageHash));
        $limitResolved = $limit;
        if ($this->newUpdates) {
            $limitResolved = $ohlcv->getLimit($symbolResolved, $limitResolved);
        }
        return $this->filter_by_since_limit($ohlcv, $since, $limitResolved, 0, true);
    }

    public function un_watch_ohlcv(string $symbol, string $timeframe = '1m', $params = array()): PromiseInterface {
        return Async\async(self::do_un_watch_ohlcv(...))($symbol, $timeframe, $params);
    }

    private function do_un_watch_ohlcv(string $symbol, string $timeframe = '1m', $params = array()) {
        /**
         * unWatches the candlestick stream
         *
         * @see https://docs.polymarket.com/perps/realtime-updates
         *
         * @param {string} $symbol unified $symbol of the $market to unwatch the candles for
         * @param {string} $timeframe the length of time each candle represents
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} status of the unwatch $request
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $symbolResolved = $this->safe_string($market, 'symbol', '');
        $wsTimeframes = $this->safe_dict($this->options, 'wsTimeframes', array());
        $interval = $this->safe_string($wsTimeframes, $timeframe, $timeframe);
        $subMessageHash = 'candles:' . $timeframe . ':' . $symbolResolved;
        $messageHash = 'unsubscribe:' . $subMessageHash;
        $channel = 'klines::' . $this->safe_string($market, 'id', '') . '::' . $interval;
        $context = array(
            'topic' => 'ohlcv',
            'symbol' => $symbolResolved,
            'timeframe' => $timeframe,
        );
        $request = $this->send_subscription('unsub', array( $channel ), array( $messageHash ), array( $subMessageHash ), $context, $params);
        $url = $this->safe_string($this->urls['api'], 'ws');
        return Async\await($this->watch($url, $messageHash, $request, $messageHash));
    }

    public function handle_ohlcv(Client $client, array $message) {
        //
        //     {
        //         "ch": "klines::1::1h",
        //         "ts": 1788547135685,
        //         "ets": 1788547135685,
        //         "sq": 35880657084,
        //         "data": [
        //             [ 1788537600000, "7724.9", "7724.9", "7724.2", "7724.2", "0.02872", 5 ]
        //         ]
        //     }
        //
        // only the candles touched by fresh trades are included, the array can be empty
        //
        $ch = $this->safe_string($message, 'ch', '');
        $parts = explode('::', $ch);
        $marketId = $this->safe_string($parts, 1);
        $interval = $this->safe_string($parts, 2);
        $market = $this->safe_market($marketId);
        $symbol = $this->safe_string($market, 'symbol', '');
        $timeframe = $this->find_timeframe($interval);
        if ($timeframe === null) {
            return;
        }
        $rows = $this->safe_list($message, 'data', array());
        $rowsLength = count($rows);
        if ($rowsLength === 0) {
            return;
        }
        if (!(is_array($this->ohlcvs) && array_key_exists($symbol ?? '', $this->ohlcvs))) {
            $this->ohlcvs[$symbol] = array();
        }
        if (!(is_array($this->ohlcvs[$symbol]) && array_key_exists($timeframe ?? '', $this->ohlcvs[$symbol]))) {
            $limit = $this->safe_integer($this->options, 'OHLCVLimit', 1000);
            $stored = new ArrayCacheByTimestamp($limit);
            $this->ohlcvs[$symbol][$timeframe] = $stored;
        }
        $ohlcv = $this->ohlcvs[$symbol][$timeframe];
        for ($i = 0; $i < count($rows); $i++) {
            $parsed = $this->parse_ohlcv($rows[$i], $market);
            $ohlcv->append($parsed);
        }
        $messageHash = 'candles:' . $timeframe . ':' . $symbol;
        $client->resolve($ohlcv, $messageHash);
    }

    public function authenticate($params = array()): PromiseInterface {
        return Async\async(self::do_authenticate(...))($params);
    }

    private function do_authenticate($params = array()) {
        /**
         * @ignore
         * authenticates the websocket connection with the session proxy $credentials, provisioning them first when needed
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} resolves once the connection is $authenticated
         */
        $credentials = Async\await($this->loadProxyCredentials());
        $url = $this->safe_string($this->urls['api'], 'ws');
        $client = $this->client($url);
        $messageHash = 'authenticated';
        $future = $client->reusableFuture($messageHash);
        $authenticated = $this->safe_value($client->subscriptions, $messageHash);
        if ($authenticated === null) {
            $id = $this->request_id();
            $pending = array(
                'method' => 'auth',
                'messageHashes' => array( $messageHash ),
                'subMessageHashes' => array( $messageHash ),
            );
            $client->subscriptions['req:' . (string) $id] = $pending;
            $request = array(
                'id' => $id,
                'req' => 'post',
                'op' => array(
                    'type' => 'auth',
                    'args' => array(
                        'proxy' => $this->safe_string($credentials, 'proxy'),
                        'secret' => $this->safe_string($credentials, 'secret'),
                    ),
                ),
            );
            $this->watch($url, $messageHash, $this->extend($request, $params), $messageHash);
        }
        return Async\await($future);
    }

    public function watch_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_orders(...))($symbol, $since, $limit, $params);
    }

    private function do_watch_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * watches information on the $orders made by the user
         *
         * @see https://docs.polymarket.com/perps/realtime-updates
         *
         * @param {string} [$symbol] unified $market $symbol of the $market the $orders were made in
         * @param {int} [$since] timestamp in ms of the earliest order
         * @param {int} [$limit] the maximum number of order structures to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=order-structure order structures~
         */
        Async\await($this->load_markets());
        Async\await($this->authenticate());
        $messageHash = 'orders';
        $symbolResolved = $symbol;
        if ($symbol !== null) {
            $market = $this->market($symbol);
            $resolvedSymbol = $this->safe_string($market, 'symbol', '');
            $symbolResolved = $resolvedSymbol;
            $messageHash = 'orders:' . $resolvedSymbol;
        }
        $subscribeHashes = array( 'orders' );
        $request = $this->send_subscription('sub', array( 'orders' ), array( $messageHash ), $subscribeHashes, array(), $params, $subscribeHashes);
        $url = $this->safe_string($this->urls['api'], 'ws');
        $orders = Async\await($this->watch($url, $messageHash, $request, 'orders'));
        $limitResolved = $limit;
        if ($this->newUpdates) {
            $limitResolved = $orders->getLimit($symbolResolved, $limitResolved);
        }
        return $this->filter_by_symbol_since_limit($orders, $symbolResolved, $since, $limitResolved, true);
    }

    public function handle_order(Client $client, array $message) {
        //
        //     {
        //         "ch": "orders",
        //         "ts": 1788546565800,
        //         "sq": 35879860000,
        //         "data": {
        //             "oid": 1234567890,
        //             "iid": 6,
        //             "buy": true,
        //             "p": "79000.0",
        //             "qty": "0.001",
        //             "tif": "gtc",
        //             "po": false,
        //             "ro": false,
        //             "rest": "0.001",
        //             "fill": "0",
        //             "cts": 1788546565789,
        //             "uts": 1788546565789,
        //             "status": "open"
        //         }
        //     }
        //
        $data = $this->safe_value($message, 'data');
        $rows = array();
        if ((gettype($data) === 'array' && array_keys($data) === array_keys(array_keys($data)))) {
            $rows = $data;
        } else {
            $rows[] = $data;
        }
        $rowsLength = count($rows);
        if ($rowsLength === 0) {
            return;
        }
        if ($this->orders === null) {
            $limit = $this->safe_integer($this->options, 'ordersLimit', 1000);
            $this->orders = new ArrayCacheBySymbolById($limit);
        }
        $stored = $this->orders;
        $symbols = array();
        for ($i = 0; $i < $rowsLength; $i++) {
            $row = $this->safe_dict($rows, $i, array());
            $parsed = $this->parse_order($row);
            $stored->append($parsed);
            $symbol = $this->safe_string($parsed, 'symbol');
            if ($symbol !== null) {
                $symbols[$symbol] = true;
            }
        }
        $client->resolve($stored, 'orders');
        $symbolKeys = is_array($symbols) ? array_keys($symbols) : array();
        for ($i = 0; $i < count($symbolKeys); $i++) {
            $symbol = $this->safe_string($symbolKeys, $i, '');
            $client->resolve($stored, 'orders:' . $symbol);
        }
    }

    public function watch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
