    public function watch_positions(?array $symbols = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_positions(...))($symbols, $since, $limit, $params);
    }

    private function do_watch_positions(?array $symbols = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * watches information on the open positions of the account, the venue pushes a full portfolio $snapshot roughly every five seconds
         *
         * @see https://docs.polymarket.com/perps/realtime-updates
         *
         * @param {string[]} [$symbols] list of unified market $symbols
         * @param {int} [$since] not used by polymarket watchPositions
         * @param {int} [$limit] not used by polymarket watchPositions
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=position-structure position structures~
         */
        Async\await($this->load_markets());
        Async\await($this->authenticate());
        $symbolsNormalized = $this->market_symbols($symbols);
        $url = $this->safe_string($this->urls['api'], 'ws');
        $client = $this->client($url);
        $this->set_positions_cache($client, $symbolsNormalized);
        $fetchPositionsSnapshot = $this->handle_option('watchPositions', 'fetchPositionsSnapshot', true);
        $awaitPositionsSnapshot = $this->handle_option('watchPositions', 'awaitPositionsSnapshot', true);
        if (($fetchPositionsSnapshot === true) && ($awaitPositionsSnapshot === true) && ($this->positions === null)) {
            // the portfolio channel pushes one snapshot at subscribe time and
            // then only on changes, so the first call hydrates over rest
            $snapshot = Async\await($client->future('fetchPositionsSnapshot'));
            return $this->filter_by_symbols_since_limit($snapshot, $symbolsNormalized, $since, $limit, true);
        }
        $subscribeHashes = array( 'portfolio' );
        $request = $this->send_subscription('sub', array( 'portfolio' ), array( 'positions' ), $subscribeHashes, array(), $params, $subscribeHashes);
        $newPositions = Async\await($this->watch($url, 'positions', $request, 'portfolio'));
        if ($this->newUpdates) {
            return $this->filter_by_symbols_since_limit($newPositions, $symbolsNormalized, $since, $limit, true);
        }
        return $this->filter_by_symbols_since_limit($this->positions, $symbolsNormalized, $since, $limit, true);
    }

    public function set_positions_cache(Client $client, ?array $symbols = null) {
        if ($this->positions !== null) {
            return;
        }
        $fetchPositionsSnapshot = $this->handle_option('watchPositions', 'fetchPositionsSnapshot', true);
        if ($fetchPositionsSnapshot === true) {
            $messageHash = 'fetchPositionsSnapshot';
            if (!(is_array($client->futures) && array_key_exists($messageHash ?? '', $client->futures))) {
                $client->future($messageHash);
                $this->spawn(array($this, 'load_positions_snapshot'), $client, $messageHash);
            }
        } else {
            $this->positions = new ArrayCacheBySymbolBySide();
        }
    }

    public function load_positions_snapshot(Client $client, string $messageHash) {
        return Async\async(self::do_load_positions_snapshot(...))($client, $messageHash);
    }

    private function do_load_positions_snapshot(Client $client, string $messageHash) {
        $positions = Async\await($this->fetch_positions());
        $this->positions = new ArrayCacheBySymbolBySide();
        $cache = $this->positions;
        for ($i = 0; $i < count($positions); $i++) {
            $cache->append($positions[$i]);
        }
        // don't remove the future from the .futures cache
        if (is_array($client->futures) && array_key_exists($messageHash ?? '', $client->futures)) {
            $future = $client->futures[$messageHash];
            $future->resolve($cache);
        }
        $client->resolve($cache, 'positions');
    }

    public function watch_balance($params = array()): PromiseInterface {
        return Async\async(self::do_watch_balance(...))($params);
    }

    private function do_watch_balance($params = array()) {
        /**
         * watches the account margin summary, the venue pushes a full portfolio $snapshot roughly every five seconds
         *
         * @see https://docs.polymarket.com/perps/realtime-updates
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=balance-structure balance structure~
         */
        Async\await($this->load_markets());
        Async\await($this->authenticate());
        $url = $this->safe_string($this->urls['api'], 'ws');
        $client = $this->client($url);
        $this->set_balance_cache($client);
        $fetchBalanceSnapshot = $this->handle_option('watchBalance', 'fetchBalanceSnapshot', true);
        $awaitBalanceSnapshot = $this->handle_option('watchBalance', 'awaitBalanceSnapshot', true);
        $balanceLoaded = (is_array($this->balance) && array_key_exists('info' ?? '', $this->balance));
        if (($fetchBalanceSnapshot === true) && ($awaitBalanceSnapshot === true) && (!$balanceLoaded)) {
            // the portfolio channel pushes one snapshot at subscribe time and
            // then only on changes, so the first call hydrates over rest
            $snapshot = Async\await($client->future('fetchBalanceSnapshot'));
            return $snapshot;
        }
        $subscribeHashes = array( 'portfolio' );
        $request = $this->send_subscription('sub', array( 'portfolio' ), array( 'balance' ), $subscribeHashes, array(), $params, $subscribeHashes);
        return Async\await($this->watch($url, 'balance', $request, 'portfolio'));
    }

    public function set_balance_cache(Client $client) {
        $balanceLoaded = (is_array($this->balance) && array_key_exists('info' ?? '', $this->balance));
        if ($balanceLoaded) {
            return;
        }
        $fetchBalanceSnapshot = $this->handle_option('watchBalance', 'fetchBalanceSnapshot', true);
        if ($fetchBalanceSnapshot === true) {
            $messageHash = 'fetchBalanceSnapshot';
            if (!(is_array($client->futures) && array_key_exists($messageHash ?? '', $client->futures))) {
                $client->future($messageHash);
                $this->spawn(array($this, 'load_balance_snapshot'), $client, $messageHash);
            }
        }
    }

    public function load_balance_snapshot(Client $client, string $messageHash) {
        return Async\async(self::do_load_balance_snapshot(...))($client, $messageHash);
    }

    private function do_load_balance_snapshot(Client $client, string $messageHash) {
        $balance = Async\await($this->fetch_balance());
        $this->balance = $this->extend($this->balance, $balance);
        // don't remove the future from the .futures cache
        if (is_array($client->futures) && array_key_exists($messageHash ?? '', $client->futures)) {
            $future = $client->futures[$messageHash];
            $future->resolve($this->balance);
        }
        $client->resolve($this->balance, 'balance');
    }

    public function handle_portfolio(Client $client, array $message) {
        //
        //     {
        //         "ch": "portfolio",
        //         "ts": 1788546565789,
        //         "sq": 35879860000,
        //         "data": {
        //             "positions": [
        //                 {
        //                     "instrument_id": 6,
        //                     "symbol": "BTC-USD",
        //                     "size": "0.001",
        //                     "entry_price": "79650.0",
        //                     "leverage": 10,
        //                     "cross": true,
        //                     "initial_margin": "7.97",
        //                     "maintenance_margin": "3.99",
        //                     "position_value": "79.65",
        //                     "liquidation_price": "72000.0",
        //                     "unrealized_pnl": "-0.10",
        //                     "return_on_equity": "-0.0125",
        //                     "cumulative_funding": "0.01",
        //                     "adl_index": 0
        //                 }
        //             ],
        //             "margin": {
        //                 "total_account_value": "100.00",
        //                 "available_order_margin": "90.00",
        //                 "total_initial_margin": "10.00",
        //                 "total_maintenance_margin": "5.00",
        //                 "total_position_value": "50.00"
        //             },
        //             "withdrawable": "90.00",
        //             "in_liquidation": false,
        //             "timestamp": 1788546565789
        //         }
        //     }
        //
        $data = $this->safe_dict($message, 'data', array());
        $timestamp = $this->safe_integer($data, 'timestamp');
        if ($this->positions === null) {
            $this->positions = new ArrayCacheBySymbolBySide();
        }
        $cache = $this->positions;
        $rows = $this->safe_list($data, 'positions', array());
        $newPositions = array();
        for ($i = 0; $i < count($rows); $i++) {
            $row = $this->safe_dict($rows, $i, array());
            $extended = $this->extend($row, array( 'timestamp' => $timestamp ));
            $position = $this->parse_position($extended);
            $newPositions[] = $position;
            $cache->append($position);
        }
        $client->resolve($newPositions, 'positions');
        $margin = $this->safe_dict($data, 'margin', array());
        $result = array(
            'info' => $data,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
        );
        $account = $this->account();
        $account['total'] = $this->safe_string($margin, 'total_account_value');
        $account['free'] = $this->safe_string($margin, 'available_order_margin');
        $account['used'] = $this->safe_string($margin, 'total_initial_margin');
        // pUSD is the only collateral asset on the venue
        $result['PUSD'] = $account;
        $this->balance = $this->safe_balance($result);
        $client->resolve($this->balance, 'balance');
    }

    public function handle_ack(Client $client, mixed $message) {
        //
        // subscribe or unsubscribe acknowledgement
        //
        //     { "id": 1, "data": [ { "status": "ok" } ] }
        //     { "id": 2, "data": [ { "status": "err", "error": "invalid channel" } ] }
        //
        // ping reply
        //
        //     { "id": 99, "ts": 1788546831854, "data": { "status": "ok", "ts": 1788546831854, "sq": 35879934302 } }
        //
        $id = $this->safe_string($message, 'id');
        $data = $this->safe_value($message, 'data');
        if ((gettype($data) !== 'array' || array_keys($data) !== array_keys(array_keys($data)))) {
            // post replies carry a data object - the auth op is matched back
            // through its pending entry, anything else counts like a pong
            if ($id !== null) {
                $postKey = 'req:' . $id;
                $postPending = $this->safe_dict($client->subscriptions, $postKey);
                if ($postPending !== null) {
                    unset($client->subscriptions[$postKey]);
                    $postAction = $this->safe_string($postPending, 'method');
                    if ($postAction === 'auth') {
                        $authStatus = $this->safe_string($data, 'status');
                        if ($authStatus === 'ok') {
                            // resolve the future object directly so it stays
                            // cached and later authenticate calls reuse it
                            $future = $this->safe_value($client->futures, 'authenticated');
                            if ($future !== null) {
                                $future->resolve(true);
                            }
                        } else {
                            $authError = new AuthenticationError($this->id . ' authentication failed ' . $this->json($data));
                            $client->reject($authError, 'authenticated');
                            if (is_array($client->subscriptions) && array_key_exists('authenticated' ?? '', $client->subscriptions)) {
                                unset($client->subscriptions['authenticated']);
                            }
                        }
                        return;
                    }
                }
            }
            $client->lastPong = $this->safe_integer($message, 'ts', $this->milliseconds());
            return;
        }
        if ($id === null) {
            return;
        }
        $key = 'req:' . $id;
        $pending = $this->safe_dict($client->subscriptions, $key);
        if ($pending === null) {
            return;
        }
        unset($client->subscriptions[$key]);
        $messageHashes = $this->safe_list($pending, 'messageHashes', array());
        $subMessageHashes = $this->safe_list($pending, 'subMessageHashes', array());
        $action = $this->safe_string($pending, 'method');
        $errorMessage = null;
        for ($i = 0; $i < count($data); $i++) {
            $entry = $this->safe_dict($data, $i, array());
            $status = $this->safe_string($entry, 'status');
            if ($status === 'err') {
                $errorMessage = $this->safe_string($entry, 'error');
            }
        }
        if ($errorMessage !== null) {
            $error = new ExchangeError($this->id . ' ' . $errorMessage);
            for ($i = 0; $i < count($messageHashes); $i++) {
                $client->reject($error, $messageHashes[$i]);
                // clearing the awaited hash lets a later call resend, and a
                // failed subscribe must also clear the shared hash the base
                // watch registered - a failed unsubscribe keeps the live
                // subscription untouched instead
                $messageHash = $messageHashes[$i];
                if (is_array($client->subscriptions) && array_key_exists($messageHash ?? '', $client->subscriptions)) {
                    unset($client->subscriptions[$messageHash]);
                }
                if ($action === 'sub') {
                    $subMessageHash = $subMessageHashes[$i];
                    if (is_array($client->subscriptions) && array_key_exists($subMessageHash ?? '', $client->subscriptions)) {
                        unset($client->subscriptions[$subMessageHash]);
                    }
                }
            }
            return;
        }
        if ($action === 'unsub') {
            $topic = $this->safe_string($pending, 'topic');
            $symbol = $this->safe_string($pending, 'symbol');
            if ($symbol !== null) {
                if ($topic === 'orderbook') {
                    if (is_array($this->orderbooks) && array_key_exists($symbol ?? '', $this->orderbooks)) {
                        unset($this->orderbooks[$symbol]);
                    }
                } elseif ($topic === 'trades') {
                    if (is_array($this->trades) && array_key_exists($symbol ?? '', $this->trades)) {
                        unset($this->trades[$symbol]);
                    }
                } elseif ($topic === 'ticker') {
                    if (is_array($this->tickers) && array_key_exists($symbol ?? '', $this->tickers)) {
                        unset($this->tickers[$symbol]);
                    }
                } elseif ($topic === 'ohlcv') {
                    $timeframe = $this->safe_string($pending, 'timeframe');
                    if (($timeframe !== null) && (is_array($this->ohlcvs) && array_key_exists($symbol ?? '', $this->ohlcvs))) {
                        if (is_array($this->ohlcvs[$symbol]) && array_key_exists($timeframe ?? '', $this->ohlcvs[$symbol])) {
                            unset($this->ohlcvs[$symbol][$timeframe]);
                        }
                    }
                }
            }
            for ($i = 0; $i < count($messageHashes); $i++) {
                $this->clean_unsubscription($client, $subMessageHashes[$i], $messageHashes[$i]);
            }
        }
    }

    public function handle_message(Client $client, mixed $message) {
        $ch = $this->safe_string($message, 'ch');
        if ($ch === null) {
            $this->handle_ack($client, $message);
            return;
        }
        $parts = explode('::', $ch);
        $family = $this->safe_string($parts, 0, '');
        $methods = array(
            'book' => array($this, 'handle_order_book'),
            'bbo' => array($this, 'handle_bid_ask'),
            'trades' => array($this, 'handle_trades'),
            'tickers' => array($this, 'handle_ticker'),
            'klines' => array($this, 'handle_ohlcv'),
            'orders' => array($this, 'handle_order'),
            'fills' => array($this, 'handle_my_trades'),
            'portfolio' => array($this, 'handle_portfolio'),
        );
        $method = $this->safe_value($methods, $family);
        if ($method !== null) {
            $method($client, $message);
        }
    }

    public function ping(Client $client) {
        return array(
            'id' => $this->request_id(),
            'req' => 'post',
            'op' => array(
                'type' => 'ping',
            ),
        );
    }
}
